/*
 * hooks.c - netfilter entry points.
 *
 *   PRE_ROUTING  (FIRST)    filter   packets arriving (to this host or forwarded)
 *   LOCAL_OUT    (FIRST)    filter   packets generated by this host
 *   PRE_ROUTING  (NAT_DST)  DNAT     and un-SNAT of replies
 *   POST_ROUTING (NAT_SRC)  SNAT     and un-DNAT of replies
 *
 * Every packet is filtered exactly once, and always before any address is
 * rewritten, so rules are written against the addresses the sender used.
 */
#include <linux/netfilter_ipv4.h>
#include <net/net_namespace.h>
#include "fw.h"

unsigned int fw_default_action = FW_ACT_ACCEPT;
unsigned int fw_log_default;
atomic64_t fw_stat_accepted, fw_stat_dropped, fw_stat_stateful, fw_stat_natted;

static unsigned int fw_filter(void *priv, struct sk_buff *skb,
			      const struct nf_hook_state *state)
{
	struct fw_tuple t;
	struct fw_rule rule;
	unsigned int action;
	bool log, by_default = false;
	u32 len;
	u8 flags;

	if (fw_pkt_tuple(skb, &t, &flags))
		return NF_DROP;                 /* truncated transport header */
	len = fw_pkt_payload_len(skb);

	/* part of a flow we already accepted (either direction) */
	if (fw_conn_lookup(&t, flags)) {
		atomic64_inc(&fw_stat_stateful);
		return NF_ACCEPT;
	}

	if (fw_rules_match(&t, len, &rule)) {
		action = rule.action;
		log = rule.log;
	} else {
		action = READ_ONCE(fw_default_action);
		log = READ_ONCE(fw_log_default);
		by_default = true;
		rule.name[0] = '\0';
	}

	if (log)
		fw_log_add(&t, len, action, by_default, rule.name);

	if (action == FW_ACT_ACCEPT) {
		fw_conn_add(&t, by_default);    /* if the table is full: accept statelessly */
		atomic64_inc(&fw_stat_accepted);
		return NF_ACCEPT;
	}
	atomic64_inc(&fw_stat_dropped);
	return NF_DROP;
}

static unsigned int fw_nat_in(void *priv, struct sk_buff *skb,
			      const struct nf_hook_state *state)
{
	struct fw_tuple t;
	u8 flags;

	if (fw_pkt_tuple(skb, &t, &flags))
		return NF_ACCEPT;
	return fw_conn_nat_pre(skb, &t);
}

static unsigned int fw_nat_out(void *priv, struct sk_buff *skb,
			       const struct nf_hook_state *state)
{
	struct fw_tuple t;
	u8 flags;

	if (fw_pkt_tuple(skb, &t, &flags))
		return NF_ACCEPT;
	return fw_conn_nat_post(skb, &t);
}

static const struct nf_hook_ops fw_ops[] = {
	{ .hook = fw_filter,  .pf = NFPROTO_IPV4, .hooknum = NF_INET_PRE_ROUTING,  .priority = NF_IP_PRI_FIRST },
	{ .hook = fw_filter,  .pf = NFPROTO_IPV4, .hooknum = NF_INET_LOCAL_OUT,    .priority = NF_IP_PRI_FIRST },
	{ .hook = fw_nat_in,  .pf = NFPROTO_IPV4, .hooknum = NF_INET_PRE_ROUTING,  .priority = NF_IP_PRI_NAT_DST },
	{ .hook = fw_nat_out, .pf = NFPROTO_IPV4, .hooknum = NF_INET_POST_ROUTING, .priority = NF_IP_PRI_NAT_SRC },
};

int fw_hooks_init(void)
{
	return nf_register_net_hooks(&init_net, fw_ops, ARRAY_SIZE(fw_ops));
}

void fw_hooks_exit(void)
{
	nf_unregister_net_hooks(&init_net, fw_ops, ARRAY_SIZE(fw_ops));
}
